'use client';

import { useCallback, useId } from 'react';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { POPULAR, SITE, type PopularPage } from './data';
import { wordsOf } from './match';
import { PageSearch } from './page-search';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  suggestionsIn,
  type SearchState,
} from './session';
import { TrailMap } from './trail-map';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function matchLineOf(state: SearchState, count: number) {
  const hasWords = wordsOf(state.query).length > 0;
  const isListed = state.isOpen && hasWords;
  if (!isListed) {
    return '';
  }
  if (count === 0) {
    return 'No page matches';
  }
  if (count === 1) {
    return '1 suggestion';
  }
  return `${count} suggestions`;
}

function PopularRow({ page }: { page: PopularPage }) {
  const Glyph = page.icon;

  return (
    <li>
      <a
        href={page.href}
        className={cn(
          'group hover:bg-foreground/[0.04] flex items-center gap-3 rounded-xl p-2 transition-colors duration-100',
          FOCUS_RING
        )}
      >
        <span className='keycap-3d flex size-8 shrink-0 items-center justify-center rounded-lg'>
          <Glyph className='text-muted-foreground size-4' />
        </span>
        <span className='flex min-w-0 flex-col'>
          <span className='text-[13px] font-medium'>{page.title}</span>
          <span className='text-muted-foreground truncate text-xs'>
            {page.lead}
          </span>
        </span>
        <ArrowRightIcon className='text-muted-foreground ms-auto size-4 shrink-0 transition-transform duration-100 group-hover:translate-x-0.5' />
      </a>
    </li>
  );
}

export default function ErrorPages01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const popularId = useId();
  const suggestions = suggestionsIn(state);
  const isFound = suggestions.length > 0;
  const matchLine = matchLineOf(state, suggestions.length);
  const message = spokenUnless(isAutoplaying, matchLine);
  const canReplay = isFinished && !isAutoplaying;

  const close = useCallback(() => act({ type: 'closed' }), [act]);

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container flex min-h-dvh w-full flex-col'
      >
        <header className='flex min-h-16 items-center gap-3 px-4 @2xl:px-8'>
          <a
            href={SITE.homeHref}
            className={cn(
              'flex items-center gap-2 rounded-md text-sm font-semibold',
              FOCUS_RING
            )}
          >
            <CompanyMark seed={SITE.name} size='lg' />
            {SITE.name}
          </a>
          <span className='flex-1' />
          <ReplayButton isShown={canReplay} onReplay={restart} label='Replay' />
        </header>

        <main className='flex flex-1 flex-col items-center px-4 pt-4 pb-16 @2xl:pt-8'>
          <div className='flex w-full max-w-xl flex-col items-center gap-8'>
            <TrailMap isFound={isFound} />

            <div className='flex flex-col items-center gap-3 text-center'>
              <p className='text-muted-foreground text-xs tabular-nums'>
                Error 404
              </p>
              <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
                Page not found
              </h1>
              <p className='text-muted-foreground max-w-md text-sm text-pretty'>
                The link may be old, or the guide moved when we grouped the
                routes by region. Search for it, or start from a popular page.
              </p>
              <p className='text-muted-foreground font-mono text-xs break-all'>
                {SITE.missingAddress}
              </p>
            </div>

            <PageSearch
              query={state.query}
              isOpen={state.isOpen}
              activeIndex={state.activeIndex}
              suggestions={suggestions}
              pressed={pressed}
              isDemonstrating={isAutoplaying}
              onType={(value) => act({ type: 'typed', value })}
              onFocus={() => act({ type: 'focused' })}
              onMove={(by) => act({ type: 'moved', by })}
              onEscape={() => act({ type: 'escaped' })}
              onClose={close}
            />

            <section
              aria-labelledby={popularId}
              className='flex w-full flex-col gap-2'
            >
              <h2 id={popularId} className='px-2 text-[13px] font-medium'>
                Popular pages
              </h2>
              <ul className='bg-foreground/[0.025] grid gap-1 rounded-2xl p-1.5 @md:grid-cols-2'>
                {POPULAR.map((page) => (
                  <PopularRow key={page.id} page={page} />
                ))}
              </ul>
            </section>

            <Button
              size='lg'
              nativeButton={false}
              render={<a href={SITE.homeHref} />}
            >
              Go home
            </Button>
          </div>
        </main>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useEffect, useId, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowRightIcon, SearchIcon } from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG, SPRING } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Input } from '@/registry/ndeko/ui/input';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { SitePage } from './data';
import { markedPartsOf, wordsOf } from './match';

const LIST_SHOWN = { opacity: 1, scale: 1 };

const LIST_HIDDEN = { opacity: 0, scale: 0.97 };

const LIST_FADED = { opacity: 0, scale: 1 };

const LIST_ARRIVE: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const LIST_LEAVE: Transition = { duration: 0.1, ease: EASE_OUT_STRONG };

const INSTANT: Transition = { duration: 0 };

const KEY_MOTION = 'transition-[scale] duration-150';

function listStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return LIST_FADED;
  }
  return LIST_HIDDEN;
}

function travelOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return SPRING;
}

function optionIdOf(listId: string, index: number) {
  return `${listId}-${index}`;
}

function activeIdOf(listId: string, activeIndex: number, isShown: boolean) {
  const hasActive = activeIndex >= 0;
  if (!isShown || !hasActive) {
    return undefined;
  }
  return optionIdOf(listId, activeIndex);
}

function MarkedTitle({ title, words }: { title: string; words: string[] }) {
  const parts = markedPartsOf(title, words);

  return (
    <span className='min-w-0 truncate'>
      {parts.map((part) => {
        if (part.isMatch) {
          return (
            <mark
              key={part.key}
              className='bg-primary/15 text-foreground rounded-[3px]'
            >
              {part.text}
            </mark>
          );
        }
        return <span key={part.key}>{part.text}</span>;
      })}
    </span>
  );
}

type PageSearchProps = {
  query: string;
  isOpen: boolean;
  activeIndex: number;
  suggestions: SitePage[];
  pressed: string | null;
  /** While the demonstration plays, the list shows without the focus and a click elsewhere leaves it be. */
  isDemonstrating: boolean;
  onType: (value: string) => void;
  onFocus: () => void;
  onMove: (by: 1 | -1) => void;
  onEscape: () => void;
  onClose: () => void;
};

export function PageSearch({
  query,
  isOpen,
  activeIndex,
  suggestions,
  pressed,
  isDemonstrating,
  onType,
  onFocus,
  onMove,
  onEscape,
  onClose,
}: PageSearchProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const wrapperRef = useRef<HTMLDivElement>(null);
  const inputId = useId();
  const listId = useId();
  const words = wordsOf(query);
  const hasWords = words.length > 0;
  const isShown = isOpen && hasWords;
  const hasSuggestions = suggestions.length > 0;
  const isListed = isShown && hasSuggestions;
  const activeId = activeIdOf(listId, activeIndex, isListed);
  const listensOutside = isShown && !isDemonstrating;

  useEffect(() => {
    if (!listensOutside) {
      return;
    }
    function closeFromOutside(event: PointerEvent) {
      const wrapper = wrapperRef.current;
      const target = event.target;
      const isInside = target instanceof Node && wrapper?.contains(target);
      if (!isInside) {
        onClose();
      }
    }
    document.addEventListener('pointerdown', closeFromOutside);
    return () => document.removeEventListener('pointerdown', closeFromOutside);
  }, [listensOutside, onClose]);

  function openActive() {
    let index = activeIndex;
    if (index < 0) {
      index = 0;
    }
    const optionId = optionIdOf(listId, index);
    const option = document.getElementById(optionId);
    option?.click();
  }

  function handleKeys(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      onMove(1);
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      onMove(-1);
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onEscape();
      return;
    }
    const isEnter = event.key === 'Enter';
    const opens = isEnter && isListed;
    if (opens) {
      event.preventDefault();
      openActive();
    }
  }

  function closeWhenLeaving(event: React.FocusEvent<HTMLDivElement>) {
    const next = event.relatedTarget;
    const staysInside =
      next instanceof Node && event.currentTarget.contains(next);
    if (!staysInside) {
      onClose();
    }
  }

  return (
    <div ref={wrapperRef} onBlur={closeWhenLeaving} className='relative w-full'>
      <label htmlFor={inputId} className='sr-only'>
        Search Larchway
      </label>
      <SearchIcon className='text-muted-foreground pointer-events-none absolute start-3.5 top-1/2 size-4 -translate-y-1/2' />
      <Input
        id={inputId}
        type='search'
        role='combobox'
        autoComplete='off'
        spellCheck={false}
        aria-autocomplete='list'
        aria-expanded={isListed}
        aria-controls={listId}
        aria-activedescendant={activeId}
        placeholder='Search routes, guides and help'
        value={query}
        onChange={(event) => onType(event.target.value)}
        onFocus={onFocus}
        onKeyDown={handleKeys}
        className='h-11 rounded-xl ps-10 pe-3 md:text-sm'
      />
      <AnimatePresence initial={false}>
        {isShown && (
          <motion.div
            key='suggestions'
            initial={listStartOf(shouldReduceMotion)}
            animate={LIST_SHOWN}
            exit={{
              ...listStartOf(shouldReduceMotion),
              transition: LIST_LEAVE,
            }}
            transition={LIST_ARRIVE}
            className='surface-raised absolute inset-x-0 top-full z-20 mt-2 flex origin-top flex-col rounded-xl p-1'
          >
            {hasSuggestions && (
              <ul
                id={listId}
                role='listbox'
                aria-label='Suggested pages'
                className='flex flex-col'
              >
                {suggestions.map((page, index) => {
                  const isActive = index === activeIndex;
                  return (
                    <li key={page.id} role='none'>
                      <a
                        id={optionIdOf(listId, index)}
                        role='option'
                        aria-selected={isActive}
                        href={page.href}
                        tabIndex={-1}
                        onMouseDown={(event) => event.preventDefault()}
                        className='relative isolate flex h-10 items-center gap-3 rounded-lg px-2.5 text-[13px] outline-none'
                      >
                        {isActive && (
                          <motion.span
                            layoutId={`${listId}-highlight`}
                            transition={travelOf(shouldReduceMotion)}
                            className='bg-foreground/[0.06] absolute inset-0 -z-10 rounded-lg'
                          />
                        )}
                        <span className='text-muted-foreground w-16 shrink-0 text-xs'>
                          {page.section}
                        </span>
                        <MarkedTitle title={page.title} words={words} />
                        <ArrowRightIcon
                          className={cn(
                            'text-muted-foreground ms-auto size-3.5 shrink-0 opacity-0 transition-opacity duration-150',
                            isActive && 'opacity-100'
                          )}
                        />
                      </a>
                    </li>
                  );
                })}
              </ul>
            )}
            {!hasSuggestions && (
              <p className='text-muted-foreground px-2.5 py-3 text-[13px] text-pretty'>
                No page matches these words. Try one place or one activity, such
                as dolomites or huts.
              </p>
            )}
            <p
              aria-hidden='true'
              className='text-muted-foreground flex flex-wrap items-center gap-x-3 gap-y-1 px-2.5 pt-2 pb-1.5 text-xs'
            >
              <span className='inline-flex items-center gap-1'>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-up')
                  )}
                >
                  ↑
                </Kbd>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-down')
                  )}
                >
                  ↓
                </Kbd>
                move
              </span>
              <span className='inline-flex items-center gap-1'>
                <Kbd>Enter</Kbd>
                opens
              </span>
              <span className='inline-flex items-center gap-1'>
                <Kbd
                  className={cn(
                    KEY_MOTION,
                    pressedQuietOf(pressed === 'key-escape')
                  )}
                >
                  Esc
                </Kbd>
                closes
              </span>
            </p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';

const LEFT_PANEL = '24,34 88,22 88,126 24,138';
const MIDDLE_PANEL = '88,22 152,34 152,138 88,126';
const RIGHT_PANEL = '152,34 216,22 216,126 152,138';

const CONTOURS = [
  'M28 62C44 54 62 60 86 48',
  'M28 84C46 78 60 86 86 74',
  'M92 104C110 96 128 108 150 100',
  'M156 110C174 100 190 106 214 94',
  'M156 82C176 74 194 80 214 70',
];

const WALKED = 'M44 112C56 98 66 100 74 88S82 72 86 68';

const LOST = 'M86 68C100 60 112 76 126 70S146 52 160 56S186 66 194 50';

const BREAK_POINT = { x: 86, y: 68 };

const END_POINT = { x: 194, y: 50 };

const PIN = 'M0 0C-2-4-6-7-6-11A6 6 0 1 1 6-11C6-7 2-4 0 0Z';

const FOUND = { pathLength: 1, opacity: 1 };

const LOST_TRAIL = { pathLength: 0, opacity: 0 };

const DRAW: Transition = { duration: 0.7, ease: EASE_OUT_STRONG };

const LET_GO: Transition = {
  opacity: { duration: 0.15 },
  pathLength: { duration: 0, delay: 0.15 },
};

const FADE: Transition = { duration: 0.2 };

/** Under reduced motion the trail is whole at once and only fades in. */
const SHOW_STILL: Transition = {
  opacity: { duration: 0.2 },
  pathLength: { duration: 0 },
};

const PIN_SHOWN = { opacity: 1, scale: 1 };

const PIN_HIDDEN = { opacity: 0, scale: 0.8 };

const PIN_FADED = { opacity: 0, scale: 1 };

const PIN_ARRIVE: Transition = {
  duration: 0.3,
  ease: EASE_OUT_STRONG,
  delay: 0.5,
};

const PIN_LEAVE: Transition = { duration: 0.12 };

/** The pin grows from its tip, where it touches the map. */
const PIN_ORIGIN = { originX: 0.5, originY: 1 };

function trailOf(isFound: boolean) {
  if (isFound) {
    return FOUND;
  }
  return LOST_TRAIL;
}

function trailMotionOf(isFound: boolean, shouldReduceMotion: boolean) {
  if (!isFound) {
    return LET_GO;
  }
  if (shouldReduceMotion) {
    return SHOW_STILL;
  }
  return DRAW;
}

function pinOf(isFound: boolean, shouldReduceMotion: boolean) {
  if (isFound) {
    return PIN_SHOWN;
  }
  if (shouldReduceMotion) {
    return PIN_FADED;
  }
  return PIN_HIDDEN;
}

function pinMotionOf(isFound: boolean, shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE;
  }
  if (isFound) {
    return PIN_ARRIVE;
  }
  return PIN_LEAVE;
}

function breakOpacityOf(isFound: boolean) {
  if (isFound) {
    return 0;
  }
  return 1;
}

type TrailMapProps = {
  isFound: boolean;
};

export function TrailMap({ isFound }: TrailMapProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const endTransform = `translate(${END_POINT.x} ${END_POINT.y})`;

  return (
    <svg
      viewBox='0 0 240 152'
      aria-hidden='true'
      className='w-full max-w-[17rem] overflow-visible'
    >
      <ellipse
        cx='120'
        cy='144'
        rx='96'
        ry='5'
        className='fill-foreground/[0.05]'
      />
      <polygon
        points={LEFT_PANEL}
        strokeWidth='1'
        vectorEffect='non-scaling-stroke'
        className='fill-card stroke-border'
      />
      <polygon
        points={MIDDLE_PANEL}
        strokeWidth='1'
        vectorEffect='non-scaling-stroke'
        className='fill-card stroke-border'
      />
      <polygon points={MIDDLE_PANEL} className='fill-foreground/[0.045]' />
      <polygon
        points={RIGHT_PANEL}
        strokeWidth='1'
        vectorEffect='non-scaling-stroke'
        className='fill-card stroke-border'
      />
      {CONTOURS.map((contour) => (
        <path
          key={contour}
          d={contour}
          fill='none'
          strokeWidth='1'
          vectorEffect='non-scaling-stroke'
          className='stroke-foreground/10'
        />
      ))}
      <path
        d={LOST}
        fill='none'
        strokeWidth='1.5'
        strokeDasharray='2 5'
        strokeLinecap='round'
        className='stroke-foreground/20'
      />
      <path
        d={WALKED}
        fill='none'
        strokeWidth='2.5'
        strokeLinecap='round'
        className='stroke-primary'
      />
      <motion.path
        d={LOST}
        fill='none'
        strokeWidth='2.5'
        strokeLinecap='round'
        className='stroke-primary'
        initial={false}
        animate={trailOf(isFound)}
        transition={trailMotionOf(isFound, shouldReduceMotion)}
      />
      <motion.circle
        cx={BREAK_POINT.x}
        cy={BREAK_POINT.y}
        r='3.5'
        strokeWidth='1.5'
        className='fill-background stroke-foreground/40'
        initial={false}
        animate={{ opacity: breakOpacityOf(isFound) }}
        transition={FADE}
      />
      <circle cx='44' cy='112' r='5' className='fill-primary' />
      <circle cx='44' cy='112' r='2' className='fill-primary-foreground' />
      <g transform={endTransform}>
        <motion.g
          style={PIN_ORIGIN}
          initial={false}
          animate={pinOf(isFound, shouldReduceMotion)}
          transition={pinMotionOf(isFound, shouldReduceMotion)}
        >
          <path d={PIN} className='fill-primary' />
          <circle cx='0' cy='-11' r='2.2' className='fill-primary-foreground' />
        </motion.g>
      </g>
    </svg>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import { PAGES } from './data';
import { suggestionsOf } from './match';

export type SearchState = {
  query: string;
  isOpen: boolean;
  /** The suggestion Enter opens. Nothing is highlighted before the arrows are used. */
  activeIndex: number;
};

export type SearchAction =
  | { type: 'typed'; value: string }
  | { type: 'focused' }
  | { type: 'moved'; by: 1 | -1 }
  | { type: 'escaped' }
  | { type: 'closed' };

type Step = SessionStep<SearchState, SearchAction>;

export const SUGGESTION_LIMIT = 5;

const NOTHING_HIGHLIGHTED = -1;

export const INITIAL: SearchState = {
  query: '',
  isOpen: false,
  activeIndex: NOTHING_HIGHLIGHTED,
};

export function suggestionsIn(state: SearchState) {
  return suggestionsOf(PAGES, state.query, SUGGESTION_LIMIT);
}

/** The first arrow lands on the first or the last row, then the highlight wraps around the list. */
function nextIndexOf(current: number, by: 1 | -1, count: number) {
  if (current === NOTHING_HIGHLIGHTED) {
    if (by === 1) {
      return 0;
    }
    return count - 1;
  }
  const moved = current + by + count;
  return moved % count;
}

function moved(state: SearchState, by: 1 | -1): SearchState {
  const count = suggestionsIn(state).length;
  if (count === 0) {
    return state;
  }
  if (!state.isOpen) {
    const firstIndex = nextIndexOf(NOTHING_HIGHLIGHTED, by, count);
    return { ...state, isOpen: true, activeIndex: firstIndex };
  }
  const activeIndex = nextIndexOf(state.activeIndex, by, count);
  return { ...state, activeIndex };
}

/** Escape closes the list first, and clears the field when the list is already closed. */
function escaped(state: SearchState): SearchState {
  if (state.isOpen) {
    return { ...state, isOpen: false, activeIndex: NOTHING_HIGHLIGHTED };
  }
  return INITIAL;
}

export function reducer(state: SearchState, action: SearchAction) {
  switch (action.type) {
    case 'typed':
      return {
        query: action.value,
        isOpen: true,
        activeIndex: NOTHING_HIGHLIGHTED,
      };
    case 'focused':
      return { ...state, isOpen: true };
    case 'moved':
      return moved(state, action.by);
    case 'escaped':
      return escaped(state);
    case 'closed':
      return { ...state, isOpen: false, activeIndex: NOTHING_HIGHLIGHTED };
  }
}

const QUERY = 'winter dolomites';

const KEY_MS = 70;

function typing(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((value, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'typed', value },
  }));
}

function arrow(after: number, by: 1 | -1): Step {
  let press = 'key-down';
  if (by === -1) {
    press = 'key-up';
  }
  return { after, by: 'demo', press, action: { type: 'moved', by } };
}

/**
 * A person types the words of the link they followed, walks the suggestions with the arrows and
 * leaves with Escape twice: the round ends on the empty field it started from.
 */
export const SCRIPT: Step[] = [
  ...typing(QUERY, 1400),
  arrow(1200, 1),
  arrow(700, 1),
  arrow(700, -1),
  {
    after: 1900,
    by: 'demo',
    press: 'key-escape',
    action: { type: 'escaped' },
  },
  { after: 800, by: 'demo', action: { type: 'escaped' } },
];

/** Under reduced motion the words are in the field and the best page is highlighted. */
export const RESTING: SearchState = {
  query: QUERY,
